 **Implementation in Various Programming Languages**

 ### C++
 ```c++
 void selectionSort(int arr[], int n) {
   for (int i = 0; i < n; i++) {
     int minIdx = i;
     for (int j = i + 1; j < n; j++) {
       if (arr[minIdx] > arr[j]) {
         minIdx = j;
       }
     }
     swap(arr, i, minIdx);
   }
 }

 void swap(int arr[], int idx1, int idx2) {
   int temp = arr[idx1];
   arr[idx1] = arr[idx2];
   arr[idx2] = temp;
 }
 ```

